const query = $json.query || {};
const headersRaw = $json.headers || {};
const headers = {};
for (const [key, value] of Object.entries(headersRaw)) {
  headers[String(key).toLowerCase()] = Array.isArray(value) ? value.join(', ') : String(value ?? '');
}

const raw = String(query.i ?? query.id ?? '').trim();
const valid = /^(PROD|LOT)-[A-Za-z0-9-]+$/i.test(raw);
const userAgent = String(headers['user-agent'] || '').trim();

function firstForwarded(value) {
  return String(value || '').split(',')[0].trim();
}

function browserInfo(ua) {
  const checks = [
    ['Edge', /Edg(?:A|iOS)?\/([\d.]+)/i],
    ['Samsung Internet', /SamsungBrowser\/([\d.]+)/i],
    ['Chrome', /(?:Chrome|CriOS)\/([\d.]+)/i],
    ['Firefox', /(?:Firefox|FxiOS)\/([\d.]+)/i],
    ['Safari', /Version\/([\d.]+).*Safari/i]
  ];
  for (const [name, re] of checks) {
    const m = ua.match(re);
    if (m) return { name, version: m[1] || null };
  }
  return { name: null, version: null };
}

function osInfo(ua) {
  let m;
  if ((m = ua.match(/Windows NT ([\d.]+)/i))) return { name: 'Windows', version: m[1] };
  if ((m = ua.match(/Android ([\d.]+)/i))) return { name: 'Android', version: m[1] };
  if ((m = ua.match(/(?:iPhone|CPU) OS ([\d_]+)/i))) return { name: 'iOS', version: m[1].replace(/_/g, '.') };
  if ((m = ua.match(/Mac OS X ([\d_]+)/i))) return { name: 'macOS', version: m[1].replace(/_/g, '.') };
  if (/Linux/i.test(ua)) return { name: 'Linux', version: null };
  return { name: null, version: null };
}

function deviceType(ua) {
  if (!ua) return null;
  if (/bot|crawler|spider|slurp|headless/i.test(ua)) return 'bot';
  if (/iPad|Tablet|Android(?!.*Mobile)/i.test(ua)) return 'tablet';
  if (/Mobile|iPhone|iPod|Android/i.test(ua)) return 'mobile';
  return 'desktop';
}

const browser = browserInfo(userAgent);
const os = osInfo(userAgent);
const forwardedFor = String(headers['x-forwarded-for'] || '').trim();
const clientIp = String(
  headers['cf-connecting-ip'] ||
  firstForwarded(forwardedFor) ||
  headers['x-real-ip'] ||
  ''
).trim();

const requestContext = {
  client_ip: clientIp || null,
  forwarded_for: forwardedFor || null,
  cf_country: headers['cf-ipcountry'] || null,
  cf_continent: headers['cf-ipcontinent'] || null,
  cf_city: headers['cf-ipcity'] || null,
  cf_region: headers['cf-region'] || null,
  cf_region_code: headers['cf-region-code'] || null,
  cf_postal_code: headers['cf-postal-code'] || null,
  cf_timezone: headers['cf-timezone'] || null,
  cf_latitude: headers['cf-iplatitude'] || null,
  cf_longitude: headers['cf-iplongitude'] || null,
  cf_metro_code: headers['cf-metro-code'] || null,
  cf_ray: headers['cf-ray'] || null,
  user_agent: userAgent || null,
  browser_name: browser.name,
  browser_version: browser.version,
  os_name: os.name,
  os_version: os.version,
  device_type: deviceType(userAgent),
  referer: headers['referer'] || headers['referrer'] || null,
  accept_language: headers['accept-language'] || null,
  request_host: headers['x-forwarded-host'] || headers['host'] || null,
  request_method: String($json.httpMethod || $json.method || 'GET').toUpperCase(),
  request_path: '/r',
  query_json: query,
  source: String(query.source || 'qr')
};

return [{
  json: {
    inventory_id: raw || null,
    inventory_id_b64: Buffer.from(raw, 'utf8').toString('base64'),
    request_context_b64: Buffer.from(JSON.stringify(requestContext), 'utf8').toString('base64'),
    valid_id: valid,
    should_redirect: false,
    response_code: valid ? 200 : 400,
    status: valid ? 'pending' : 'invalid_id',
    message: valid
      ? null
      : 'QR URL requires i=PROD-* or i=LOT-*.'
  }
}];

parameters.query:
{{ `SELECT r.*,
  '${String($json.request_context_b64 || '').replace(/'/g, "''")}'::text AS request_context_b64
FROM public.mp_qr_resolve_inventory(
  convert_from(
    decode('${String($json.inventory_id_b64 || '').replace(/'/g, "''")}', 'base64'),
    'UTF8'
  )
) AS r;` }}

parameters.jsCode:
const row = $json || {};
const status = String(row.status || 'resolver_error');
const entityType = String(row.entity_type || '').toLowerCase();
const inventoryId = String(row.inventory_id || '').trim();
const routeKind = String(row.route_kind || '').trim().toLowerCase();

function failure(code, message) {
  return [{
    json: {
      ...row,
      should_redirect: false,
      response_code: code,
      message: message || row.message || 'QR destination could not be resolved.'
    }
  }];
}

function absoluteHttpUrl(value) {
  const url = String(value || '').trim();

  if (!/^https?:\/\/[^\s]+$/i.test(url)) {
    throw new Error('Destination must be an absolute HTTP(S) URL.');
  }

  return url;
}

function appendQuery(baseUrl, params) {
  const raw = absoluteHttpUrl(baseUrl);
  const hashPos = raw.indexOf('#');
  const fragment = hashPos >= 0 ? raw.slice(hashPos) : '';
  const base = hashPos >= 0 ? raw.slice(0, hashPos) : raw;

  let separator;
  if (!base.includes('?')) {
    separator = '?';
  } else if (base.endsWith('?') || base.endsWith('&')) {
    separator = '';
  } else {
    separator = '&';
  }

  const query = Object.entries(params)
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(String(value))}`)
    .join('&');

  return `${base}${separator}${query}${fragment}`;
}

if (status !== 'ok') {
  const code =
    status === 'not_found' ? 404 :
    status === 'product_unmapped' ? 404 :
    status === 'ambiguous_mapping' ? 409 :
    status === 'invalid_id' ? 400 :
    500;

  return failure(code, row.message);
}

let target;

try {
  if (entityType === 'product') {
    if (routeKind === 'product_internal') {
      const productsUrl = String($env.MP_APP_PRODUCTS_URL || '').trim();
      if (!productsUrl) {
        return failure(503, 'Product tray QR routing is not configured: MP_APP_PRODUCTS_URL is missing.');
      }
      target = appendQuery(productsUrl, {
        product: inventoryId,
        source: 'qr'
      });
    } else if (routeKind === 'regulated_business') {
      const regulatedBusinessUrl = String($env.MP_REGULATED_BUSINESS_URL || '').trim();
      if (!regulatedBusinessUrl) {
        return failure(503, 'Regulated Product QR routing is not configured: MP_REGULATED_BUSINESS_URL is missing.');
      }
      // Regulated freeze-dried/capsule labels intentionally land on the base
      // organization website; the exact Product scan is captured by QR logs.
      target = absoluteHttpUrl(regulatedBusinessUrl);
    } else {
      const publicUrl = String(row.public_url || '').trim();
      if (!publicUrl) {
        return failure(404, `Product ${inventoryId} has no public ecommerce URL.`);
      }
      target = appendQuery(publicUrl, {
        mp_product: inventoryId,
        source: 'qr'
      });
    }
  } else if (entityType === 'lot') {
    const lotsUrl = String($env.MP_APP_LOTS_URL || '').trim();
    if (!lotsUrl) {
      return failure(503, 'Lot QR routing is not configured: MP_APP_LOTS_URL is missing.');
    }
    target = appendQuery(lotsUrl, {
      lot: inventoryId,
      source: 'qr'
    });
  } else {
    return failure(500, `Unsupported resolver entity type: ${entityType || '(blank)'}`);
  }
} catch (error) {
  return failure(500, `QR destination URL is invalid: ${error.message}`);
}

return [{
  json: {
    ...row,
    should_redirect: true,
    response_code: 302,
    redirect_url: target,
    message: null
  }
}];

const row = $json || {};

function decodeContext(value) {
  try {
    if (!value) return {};
    return JSON.parse(Buffer.from(String(value), 'base64').toString('utf8'));
  } catch (_) {
    return {};
  }
}

const context = decodeContext(row.request_context_b64);
const response = { ...row };
delete response.request_context_b64;

const payload = {
  ...context,
  inventory_id: row.inventory_id || null,
  entity_type: row.entity_type || null,
  entity_nocopk: row.entity_nocopk ?? null,
  status: row.status || 'unknown',
  route_kind: row.route_kind || null,
  response_code: Number(row.response_code || 500),
  destination_url: row.redirect_url || row.public_url || null,
  success: row.should_redirect === true,
  ecommerce_id: row.ecommerce_id ?? null,
  provider: row.provider || null,
  site_key: row.site_key || null,
  company_key: row.company_key || null,
  company_name: row.company_name || null,
  item_category: row.item_category || null,
  regulated: row.regulated ?? null,
  package_class: row.package_class || null,
  metadata: {
    resolver_message: row.message || null
  }
};

return [{
  json: {
    qr_log_payload_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    response_passthrough_b64: Buffer.from(JSON.stringify(response), 'utf8').toString('base64')
  }
}];

parameters.query:
{{ `WITH logged AS (
  SELECT public.mp_qr_log_scan(
    convert_from(
      decode('${String($json.qr_log_payload_b64 || '').replace(/'/g, "''")}', 'base64'),
      'UTF8'
    )::jsonb
  ) AS qr_scan_log_id
)
SELECT
  qr_scan_log_id,
  convert_from(
    decode('${String($json.response_passthrough_b64 || '').replace(/'/g, "''")}', 'base64'),
    'UTF8'
  )::jsonb AS response_json
FROM logged;` }}

