const row = $json || {};
let response = row.response_json || {};
if (typeof response === 'string') {
  try { response = JSON.parse(response); } catch (_) { response = {}; }
}
return [{
  json: {
    ...(response || {}),
    qr_scan_log_id: row.qr_scan_log_id ?? null
  }
}];
